function validate([phrases]) {
  if (!Array.isArray(phrases) || phrases.length < 1 || phrases.length > 100) return 'phrases needs 1 to 100 phrases.';
  for (const phrase of phrases) {
    if (typeof phrase !== 'string' || phrase.length < 1 || phrase.length > 100) return 'Each phrase has 1 to 100 characters.';
    if (!/^[a-z]+( [a-z]+)*$/.test(phrase)) return 'A phrase is lowercase words joined by single spaces, with no space at either end.';
  }
  return null;
}

