function beforeAndAfterPuzzles(phrases) {
  const startsWith = new Map();
  for (let i = 0; i < phrases.length; i++) {
    const first = phrases[i].split(' ')[0];
    if (!startsWith.has(first)) {
      startsWith.set(first, []);
    }
    startsWith.get(first).push(i);
  }

  const puzzles = new Set();
  for (let i = 0; i < phrases.length; i++) {
    const words = phrases[i].split(' ');
    const last = words[words.length - 1];
    const partners = startsWith.get(last) ?? [];
    for (const j of partners) {
      if (j === i) {
        continue;
      }
      const rest = phrases[j].slice(last.length);
      puzzles.add(phrases[i] + rest);
    }
  }
  return [...puzzles].sort();
}

