function beforeAndAfterPuzzles(phrases) {
  const found = [];
  for (let i = 0; i < phrases.length; i++) {
    for (let j = 0; j < phrases.length; j++) {
      if (i === j) continue;
      const a = phrases[i].split(' ');
      const b = phrases[j].split(' ');
      if (a[a.length - 1] !== b[0]) continue;
      const merged = a.concat(b.slice(1)).join(' ');
      if (!found.includes(merged)) found.push(merged);
    }
  }
  for (let i = 1; i < found.length; i++) {
    for (let k = i; k > 0 && found[k - 1] > found[k]; k--) {
      const t = found[k]; found[k] = found[k - 1]; found[k - 1] = t;
    }
  }
  return found;
}

