function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const vocab = large
    ? ['a', 'ab', 'b', 'ba', 'code', 'cod', 'rocks', 'mission', 'bar', 'soap', 'eat', 'block', 'party', 'x', 'xy', 'words']
    : ['a', 'ab', 'b', 'ba', 'c'];
  const words = large ? int(4, vocab.length) : int(2, vocab.length);
  const count = large ? 100 : int(1, 7);
  const phrases = [];
  for (let i = 0; i < count; i++) {
    if (i > 0 && rand() < 0.15) {
      phrases.push(phrases[int(0, i - 1)]);
      continue;
    }
    const length = large ? int(1, 12) : int(1, 3);
    const parts = [];
    for (let k = 0; k < length; k++) parts.push(vocab[int(0, words - 1)]);
    let phrase = parts.join(' ');
    while (phrase.length > 100) phrase = phrase.slice(0, phrase.lastIndexOf(' '));
    phrases.push(phrase);
  }
  return [phrases];
}
